"""Same-object scalar FRINTP/M full-state fixture generation."""
import json
RECORDS='\n#pragma once\n#include <stdint.h>\n#include <stdio.h>\n#include <string.h>\ntypedef struct{const char*name;unsigned width,rd,rn,rm,cond,original;} FRINTCase;\nstatic const FRINTCase cases[]={\n#define CASE(name,w,d,n,m,c,o) {#name,w,d,n,m,c,o},\n#include "frint_cases.h"\n#undef CASE\n};\n#define CASE_COUNT ((unsigned)(sizeof(cases)/sizeof(cases[0])))\nstatic uint64_t get64(const uint8_t*p){uint64_t v;memcpy(&v,p,8);return v;}\nstatic void put64(uint8_t*p,uint64_t v){memcpy(p,&v,8);}\nstatic uint64_t scalar(const uint8_t*p,unsigned width){return width==32?(uint32_t)get64(p):get64(p);}\nstatic uint64_t round_expected(uint64_t raw,unsigned width,unsigned plus,uint64_t fpcr,uint64_t*fpsr){\n const unsigned frac=width==32?23:52,bias=width==32?127:1023;\n const uint64_t limit=width==32?UINT64_C(0xffffffff):UINT64_MAX,sign=UINT64_C(1)<<(width-1),mask=(UINT64_C(1)<<frac)-1,exp=limit&~(sign|mask),quiet=UINT64_C(1)<<(frac-1);\n raw&=limit;uint64_t fraction=raw&mask;unsigned encoded=(unsigned)((raw&exp)>>frac);int negative=!!(raw&sign);\n if((raw&exp)==exp){if(!fraction)return raw;if(!(fraction&quiet))*fpsr|=1;return(fpcr&(UINT64_C(1)<<25))?exp|quiet:raw|quiet;}\n if(!encoded){if(!fraction)return raw;if(fpcr&(UINT64_C(1)<<24)){*fpsr|=128;return raw&sign;}}\n int exponent=(int)encoded-(int)bias;int away=plus?!negative:negative;\n if(exponent<0)return(raw&sign)|(away?((uint64_t)bias<<frac):0);\n if(exponent>=(int)frac)return raw;\n uint64_t step=UINT64_C(1)<<(frac-(unsigned)exponent);return(raw&(step-1))?((raw&~(step-1))+(away?step:0)):raw;\n}\nstatic int run_frint_records(void(*call)(unsigned,uint8_t*,const uint8_t*)){\n static const uint64_t f32[]={UINT64_C(0x0),UINT64_C(0x1),UINT64_C(0x2),UINT64_C(0x7fffff),UINT64_C(0x800000),UINT64_C(0x3e800000),UINT64_C(0x3effffff),UINT64_C(0x3f000000),UINT64_C(0x3f000001),UINT64_C(0x3f7fffff),UINT64_C(0x3f800000),UINT64_C(0x3f800001),UINT64_C(0x3fc00000),UINT64_C(0x3fffffff),UINT64_C(0x40000000),UINT64_C(0x40000001),UINT64_C(0x40200000),UINT64_C(0x4affffff),UINT64_C(0x4b000000),UINT64_C(0x4b000001),UINT64_C(0x7f7fffff),UINT64_C(0x7f800000),UINT64_C(0x7f800001),UINT64_C(0x7fbfffff),UINT64_C(0x7fc00000),UINT64_C(0x7fc12345),UINT64_C(0x7fffffff),UINT64_C(0x80000000),UINT64_C(0x80000001),UINT64_C(0x80000002),UINT64_C(0x807fffff),UINT64_C(0x80800000),UINT64_C(0xbe800000),UINT64_C(0xbeffffff),UINT64_C(0xbf000000),UINT64_C(0xbf000001),UINT64_C(0xbf7fffff),UINT64_C(0xbf800000),UINT64_C(0xbf800001),UINT64_C(0xbfc00000),UINT64_C(0xbfffffff),UINT64_C(0xc0000000),UINT64_C(0xc0000001),UINT64_C(0xc0200000),UINT64_C(0xcaffffff),UINT64_C(0xcb000000),UINT64_C(0xcb000001),UINT64_C(0xff7fffff),UINT64_C(0xff800000),UINT64_C(0xff800001),UINT64_C(0xffbfffff),UINT64_C(0xffc00000),UINT64_C(0xffc12345),UINT64_C(0xffffffff)};\n static const uint64_t f64[]={UINT64_C(0x0),UINT64_C(0x1),UINT64_C(0x2),UINT64_C(0xfffffffffffff),UINT64_C(0x10000000000000),UINT64_C(0x3fd0000000000000),UINT64_C(0x3fdfffffffffffff),UINT64_C(0x3fe0000000000000),UINT64_C(0x3fe0000000000001),UINT64_C(0x3fefffffffffffff),UINT64_C(0x3ff0000000000000),UINT64_C(0x3ff0000000000001),UINT64_C(0x3ff8000000000000),UINT64_C(0x3fffffffffffffff),UINT64_C(0x4000000000000000),UINT64_C(0x4000000000000001),UINT64_C(0x4004000000000000),UINT64_C(0x432fffffffffffff),UINT64_C(0x4330000000000000),UINT64_C(0x4330000000000001),UINT64_C(0x7fefffffffffffff),UINT64_C(0x7ff0000000000000),UINT64_C(0x7ff0000000000001),UINT64_C(0x7ff7ffffffffffff),UINT64_C(0x7ff8000000000000),UINT64_C(0x7ff8123456789abc),UINT64_C(0x7fffffffffffffff),UINT64_C(0x8000000000000000),UINT64_C(0x8000000000000001),UINT64_C(0x8000000000000002),UINT64_C(0x800fffffffffffff),UINT64_C(0x8010000000000000),UINT64_C(0xbfd0000000000000),UINT64_C(0xbfdfffffffffffff),UINT64_C(0xbfe0000000000000),UINT64_C(0xbfe0000000000001),UINT64_C(0xbfefffffffffffff),UINT64_C(0xbff0000000000000),UINT64_C(0xbff0000000000001),UINT64_C(0xbff8000000000000),UINT64_C(0xbfffffffffffffff),UINT64_C(0xc000000000000000),UINT64_C(0xc000000000000001),UINT64_C(0xc004000000000000),UINT64_C(0xc32fffffffffffff),UINT64_C(0xc330000000000000),UINT64_C(0xc330000000000001),UINT64_C(0xffefffffffffffff),UINT64_C(0xfff0000000000000),UINT64_C(0xfff0000000000001),UINT64_C(0xfff7ffffffffffff),UINT64_C(0xfff8000000000000),UINT64_C(0xfff8123456789abc),UINT64_C(0xffffffffffffffff)};\n unsigned count=0;\n for(unsigned test=0;test<CASE_COUNT;++test)for(unsigned seed=0;seed<4096;++seed){\n  const FRINTCase*c=&cases[test];unsigned pattern=seed&127,flags=(seed>>8)&15,mode=(seed>>7)&15;\n  uint8_t input[768] __attribute__((aligned(16))),output_space[1664] __attribute__((aligned(16))),expected[800],original[768];uint8_t*out=output_space+32;\n  memset(input,0x73,sizeof(input));memset(output_space,0xab,sizeof(output_space));uint64_t random=UINT64_C(0x9e3779b97f4a7c15)^seed;\n  for(unsigned n=0;n<92;++n){random^=random<<13;random^=random>>7;random^=random<<17;put64(input+n*8,random);}\n  const uint64_t*edge=c->width==32?f32:f64;uint64_t a=pattern<64?edge[pattern%54]:get64(input+224+c->rn*16);\n  if(c->width==32){memcpy(input+224+c->rn*16,&a,4);}else{put64(input+224+c->rn*16,a);}\n  put64(input+736,(uint64_t)flags<<28);put64(input+744,((seed>>11)&1)?UINT64_C(0x0800009f):0);put64(input+752,((uint64_t)(mode&3)<<22)|((uint64_t)(mode&12)<<22));\n  memcpy(original,input,sizeof(input));call(test,out,input);\n  if(memcmp(original,input,sizeof(input)))return 20;\n  for(unsigned n=0;n<sizeof(output_space);++n)if((n<32||n>=1632)&&output_space[n]!=0xab)return 21;\n  if(get64(out)!=(uintptr_t)out||get64(out+8)!=(uintptr_t)input||!get64(out+240)||get64(out+248)%16)return 22;\n  for(unsigned reg=2;reg<30;++reg)if(reg!=18&&get64(out+reg*8)!=get64(input+(reg-2)*8))return 23;\n  if(memcmp(out+256,input+224,512)||get64(out+768)!=get64(input+736)||get64(out+776)!=get64(input+744)||get64(out+784)!=get64(input+752))return 24;\n  memcpy(expected,out,800);uint64_t status=get64(out+776);uint64_t selected=round_expected(scalar(out+256+c->rn*16,c->width),c->width,c->cond,get64(out+784),&status);put64(expected+776,status);\n  memset(expected+256+c->rd*16,0,16);put64(expected+256+c->rd*16,selected);\n  if(memcmp(expected,out+800,800)){fprintf(stderr,"FRINT bit/state mismatch case=%s seed=%u\\n",c->name,seed);return 25;}\n  put64(expected,0);put64(expected+8,0);put64(expected+18*8,0);put64(expected+30*8,0);put64(expected+31*8,0);\n  uint64_t hash=UINT64_C(1469598103934665603);for(unsigned n=0;n<800;++n){hash^=expected[n];hash*=UINT64_C(1099511628211);}\n  printf("RECORD %s %u %016llx %016llx\\n",c->name,seed,(unsigned long long)selected,(unsigned long long)hash);++count;\n }\n printf("FRINT-RECORDS-SUCCESS %u\\n",count);return 0;\n}\n'

def generate(out):
 cases=[]
 for width in(32,64):
  for plus in(0,1):
   for rd,rn in((0,1),(8,8),(31,17)):
    word=((0x1e24c000 if width==32 else 0x1e64c000)+(0 if plus else 0x8000))|(rn<<5)|rd
    cases.append((f'frint{"p"if plus else"m"}_{width}_{rd}_{rn}',width,rd,rn,0,plus,0,[word]))
 for name,w,d,n,plus,word in[("original_p_s",32,8,0,1,0x1e24c008),("original_m_s",32,0,0,0,0x1e254000),("original_p_d",64,0,0,1,0x1e64c000),("original_m_d",64,0,0,0,0x1e654000)]:
  cases.append((name,w,d,n,0,plus,0,[word]))
 lines=['.text']
 def function(name,body):lines.extend([f'.global {name}',f'.type {name},%function',f'{name}:','.cfi_startproc',*['  '+x for x in body],'.cfi_endproc',f'.size {name},.-{name}'])
 def snapshot(offset):
  b=[f'str x{r},[x0,#{offset+r*8}]'for r in range(31)]+[f'str q{r},[x0,#{offset+256+r*16}]'for r in range(32)]
  b+=['mov x2,sp',f'str x2,[x0,#{offset+248}]','cset x2,mi','lsl x2,x2,#31','cset x3,eq','orr x2,x2,x3,lsl#30','cset x3,cs','orr x2,x2,x3,lsl#29','cset x3,vs','orr x2,x2,x3,lsl#28',f'str x2,[x0,#{offset+768}]']
  for register,pos in(('fpsr',776),('fpcr',784)):b+=[f'mrs x2,{register}',f'str x2,[x0,#{offset+pos}]']
  return b+[f'ldr x2,[x0,#{offset+16}]',f'ldr x3,[x0,#{offset+24}]']
 for name,w,d,n,m,c,kind,words in cases:
  body=['sub sp,sp,#240']+[f'stp x{r},x{r+1},[sp,#{(r-18)*8}]'for r in range(18,30,2)]+['str x30,[sp,#96]']+[f'str q{r},[sp,#{112+(r-8)*16}]'for r in range(8,16)]
  for register,pos in(('fpsr',744),('fpcr',752)):body+=[f'ldr x2,[x1,#{pos}]',f'msr {register},x2']
  body +=[f'ldr q{r},[x1,#{224+r*16}]'for r in range(32)]+[f'ldr x{r},[x1,#{(r-2)*8}]'for r in range(2,30)if r!=18]
  body+=snapshot(0)+[f'.inst 0x{x:08x}'for x in words]+snapshot(800)
  body+=[f'ldr q{r},[sp,#{112+(r-8)*16}]'for r in range(8,16)]+[f'ldp x{r},x{r+1},[sp,#{(r-18)*8}]'for r in range(18,30,2)]+['ldr x30,[sp,#96]','add sp,sp,#240','ret']
  function(name,body);function('raw_'+name,[*[f'.inst 0x{x:08x}'for x in words],'ret'])
 function('frint_control_copy',['ldr s0,[x0]','str s0,[x1]','ret'])
 (out/'frint.S').write_text('\n'.join(lines)+'\n');(out/'frint_cases.h').write_text(''.join(f'CASE({n},{w},{d},{rn},{rm},{c},{o})\n'for n,w,d,rn,rm,c,o,_ in cases));(out/'frint_records.h').write_text(RECORDS);(out/'case-oracle.json').write_text(json.dumps(cases,indent=2)+'\n');return cases
